#pragma once
// Language selection + translated string lookup.
//
// The Str enum and the per-language tables live in app/lang/ (generated by
// tools/gen_lang.py). Tr() returns the current language's entry; the tables
// are pure-ASCII headers with \uXXXX escapes, so no compiler codepage
// settings are involved.

#include "common.h"

#include "app/lang/StrTable.h"

namespace micp {
namespace lang {

enum class LangId
{
    De = 0,   // de_DE
    En,       // en_US
    Ja,       // ja_JP
    NlBe,     // nl_BE
    NlNl,     // nl_NL
    PtBr,     // pt_BR
    PtPt,     // pt_PT
    Ru,       // ru_RU
    Tr,       // tr_TR
    Uk,       // uk_UA
    ZhCn,     // zh_CN
    ZhTw,     // zh_TW
    Count
};

constexpr int kLangCount = int(LangId::Count);

// Active language (zh_CN until SetLang runs at startup).
LangId Current();

// Switch the active table. The caller owns the aftermath: rebuild fonts,
// relayout and repaint (see App::ApplyLang).
void SetLang(LangId id);

// Fixed endonym for the picker, Minecraft-style: "Deutsch (Deutschland)",
// "English (US)", "日本語 (日本)" ... never translated.
const wchar_t* DisplayName(LangId id);

// Locale code, e.g. L"de_DE" (kept for future INI round-trips).
const wchar_t* Code(LangId id);

// Translate a string id in the current language. Always valid; falls back
// to zh_CN (and then to L"") on an out-of-range id.
const wchar_t* Tr(Str s);

// Map a system locale name ("zh-CN", "pt-BR", "nl-BE", ...) onto one of the
// supported languages. Unmatched locales fall back to zh_CN, the app's
// historical default.
LangId FromLocale(const wchar_t* locale);

// GetUserDefaultLocaleName -> FromLocale.
LangId DetectSystemLang();

// CJK companion face that renders the active language's script best:
// YaHei (zh_CN), JhengHei (zh_TW), Yu Gothic (ja_JP). Used by Theme's
// RebuildFonts for the per-role cjk slot.
const wchar_t* CjkFontFace();

// True when the language's UI copy is CJK and its EDIT fields should use
// the cjk face instead of the latin one.
bool UsesCjkFace();

} // namespace lang
} // namespace micp
